  'dash.settings.autonomous_confirm': 'Passer en mode Autonome ?\n\nCela approuve automatiquement chaque catégorie d\'outils — bash, git, file_write, file_edit, database_query, browser, http_request — y compris leur sous-ensemble destructeur (rm, format, deletes, overwrites). Les seules opérations qui demandent encore confirmation sont les modèles irréversibles (force-push, hard reset, history rewrites, package publish, git_commit --amend) — ceux-là ne passent jamais au niveau supérieur.\n\nChoisissez ceci uniquement si vous voulez qu\'Ava fonctionne sans confirmations lors de longues sessions, et uniquement sur un espace de travail où vous pouvez récupérer après une mauvaise écriture via git.',
