  'dash.settings.custom_banner': 'Personnalisé — vous avez ajusté des catégories individuelles. Sélectionnez un préréglage ci-dessus pour réinitialiser.',
  'dash.settings.custom_model': 'Modèle personnalisé',
  'dash.settings.custom_model_desc': 'Pointez Ava vers n\'importe quel modèle — local (Ollama, LM Studio, vLLM sur votre machine) ou distant (cluster vLLM privé, finetune auto-hébergé, OpenRouter, Together, tout ce qui parle l\'API OpenAI Chat Completions). Les serveurs locaux restent sur votre machine ; les points de terminaison distants obtiennent la sécurité que votre point de terminaison expose. Redémarrez le panneau de discussion après avoir enregistré pour que les modifications prennent effet.',
